import{_ as a,o as r,c as i,a2 as s}from"./chunks/framework.iXqqCa-C.js";const p="/images/third-party-icons.webp",o="/images/third-party-aria-appstore.webp",e="/images/third-party-miria-appstore.webp",n="/images/third-party-group-files.webp",c="/images/third-party-group-downloads.webp",m="/images/aria-settings.webp",l="/images/aria-account.webp",g="/images/aria-add-account.webp",_="/images/aria-server-url.webp",d="/images/aria-select-account.webp",h="/images/aria-auth-request.webp",u="/images/aria-allow.webp",b="/images/aria-allowed.webp",f="/images/aria-authenticated.webp",A="/images/token-entry.webp",k="/images/token-permissions.webp",w="/images/token-created.webp",y="/images/token-notification.webp",P="/images/token-login.webp",q="/images/token-form.webp",$=JSON.parse('{"title":"第三方应用","description":"","frontmatter":{},"headers":[],"relativePath":"guide/third-party.md","filePath":"guide/third-party.md","lastUpdated":1793501934000}'),S={name:"guide/third-party.md"};function v(x,t,I,N,O,T){return r(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="第三方应用" tabindex="-1">第三方应用 <a class="header-anchor" href="#第三方应用" aria-label="Permalink to &quot;第三方应用&quot;">​</a></h1><p>社区支持<strong>网页端和<a href="/guide/clients/official">官方 App</a></strong>。以下第三方 Misskey 客户端由第三方开发，<strong>不由阈界人格项目组维护</strong>，项目组不提供支持。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>第三方客户端<strong>完全不支持智能体</strong>（广场、会话、记忆、生图等均不可用），也可能与本站的定制功能不兼容。</p></div><h2 id="应用介绍与下载" tabindex="-1">应用介绍与下载 <a class="header-anchor" href="#应用介绍与下载" aria-label="Permalink to &quot;应用介绍与下载&quot;">​</a></h2><p>常用的第三方客户端：</p><ul><li><strong>Aria</strong>：<a href="https://github.com/poppingmoon/aria" target="_blank" rel="noreferrer">GitHub</a></li><li><strong>miria</strong>：<a href="https://github.com/shiosyakeyakini-info/miria" target="_blank" rel="noreferrer">GitHub</a></li></ul><p><img src="'+p+'" alt="Aria 与 miria 图标"></p><p>iOS / macOS 用户可直接前往 App Store 下载：</p><p><img src="'+o+'" alt="Aria App Store 页面"></p><p><img src="'+e+'" alt="miria App Store 页面"></p><p>中国大陆区 App Store 暂未上架 miria。</p><p>也可以在官方 Q 群（519308434）的群文件中下载：</p><p><img src="'+n+'" alt="群文件中的 Misskey 软件文件夹"></p><p><img src="'+c+'" alt="群文件中的各平台安装包"></p><h2 id="登录-以-aria-为例" tabindex="-1">登录（以 Aria 为例） <a class="header-anchor" href="#登录-以-aria-为例" aria-label="Permalink to &quot;登录（以 Aria 为例）&quot;">​</a></h2><p>首次使用先添加账户：依次点击 <strong>设置 → 账户 → 添加账户</strong>。</p><p><img src="'+m+'" alt="点击设置"></p><p><img src="'+l+'" alt="点击账户"></p><p><img src="'+g+'" alt="点击添加账户"></p><p>接下来有两种登录方式：</p><ul><li><strong>OAuth 登录</strong>：推荐，无需手动处理令牌。</li><li><strong>API 登录</strong>：仅在 OAuth 登录不可用时使用，需要手动生成访问令牌，令牌有泄露风险。</li></ul><h3 id="oauth-登录" tabindex="-1">OAuth 登录 <a class="header-anchor" href="#oauth-登录" aria-label="Permalink to &quot;OAuth 登录&quot;">​</a></h3><p>在服务器地址中输入 <code>https://misskey.liminalselves.top</code>：</p><p><img src="'+_+'" alt="输入服务器地址"></p><p>点击 <strong>验证账户</strong>，跳转到授权页面后选择要登录的账户，点击继续：</p><p><img src="'+d+'" alt="选择账户"></p><p>Aria 请求授权，点击允许：</p><p><img src="'+h+'" alt="Aria 授权请求"></p><p><img src="'+u+'" alt="点击允许"></p><p><img src="'+b+'" alt="已允许访问"></p><p>返回 Aria，点击 <strong>已认证</strong> 即可登录：</p><p><img src="'+f+'" alt="点击已认证"></p><p>登录失败时，重做以上步骤，或改用下面的 API 登录。</p><h3 id="api-登录" tabindex="-1">API 登录 <a class="header-anchor" href="#api-登录" aria-label="Permalink to &quot;API 登录&quot;">​</a></h3><p>先在社区网页端依次点击 <strong>设置 → 连接服务 → 生成访问令牌</strong>：</p><p><img src="'+A+'" alt="生成访问令牌入口"></p><p>设置令牌权限，启用全部即可：</p><p><img src="'+k+'" alt="令牌权限设置"></p><p>点击 <strong>完成</strong> 后生成访问令牌：</p><p><img src="'+w+'" alt="令牌生成成功"></p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>令牌只在生成时显示一次。它具有账号的完整访问权限，不要泄露给任何人。</p></div><p><img src="'+y+'" alt="令牌创建通知"></p><p>令牌泄露时的处理见<a href="/guide/faq#访问令牌泄露了怎么办">常见问题</a>。</p><p>返回 Aria，点击右上角 <strong>…</strong>，选择 <strong>使用访问令牌登录</strong>：</p><p><img src="'+P+'" alt="使用令牌登录"></p><p>在 <strong>服务器地址</strong> 填入 <code>https://misskey.liminalselves.top</code>，在 <strong>访问令牌</strong> 填入刚生成的令牌：</p><p><img src="'+q+'" alt="填写服务器地址与访问令牌"></p><p>点击登录即可完成。仍然失败时请<a href="/guide/faq#联系项目组">联系项目组</a>。</p>',48)])])}const R=a(S,[["render",v]]);export{$ as __pageData,R as default};
